    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def numSubmatrixSumTarget(self, matrix: List[List[int]], target: int) -> int:\n        def subarraySum(nums: List[int], k: int) -> int:\n            mp = Counter([0])\n            count = pre = 0\n            for x in nums:\n                pre += x\n                if pre - k in mp:\n                    count += mp[pre - k]\n                mp[pre] += 1\n            return count\n        \n        m, n = len(matrix), len(matrix[0])\n        ans = 0\n        # \u679a\u4e3e\u4e0a\u8fb9\u754c\n        for i in range(m):\n            total = [0] * n\n            # \u679a\u4e3e\u4e0b\u8fb9\u754c\n            for j in range(i, m):\n                for c in range(n):\n                    # \u66f4\u65b0\u6bcf\u5217\u7684\u5143\u7d20\u548c\n                    total[c] += matrix[j][c]\n                ans += subarraySum(total, target)\n        \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.numSubmatrixSumTarget(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
