    "\u8f93\u51fa long \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def numGoodSubarrays(self, nums: List[int], k: int) -> int:\n        '''\n        \u679a\u4e3e\u53f3\u8fb9\u754c\n        \u53bb\u91cd\u53ea\u9700\u8981\u5173\u6ce8\u6240\u6709\u503c\u76f8\u540c\u7684\u5b50\u6570\u7ec4\n        \u524d\u7f00\u548c\n        '''\n        n = len(nums)\n        res = 0\n        dt = Counter()\n        dt[0] += 1\n        pre = 0\n        for num in nums:\n            pre += num\n            pre %= k\n            res += dt[pre]\n            dt[pre] += 1\n        \n        # \u53bb\u91cd\n        # t \u4e2a num\n        def getTotal(num,t):\n            res = 0\n            # i \u4e2a num\n            for i in range(1,t+1):\n                if (i * num) % k == 0:\n                    # t - i + 1\n                    res += t - i\n            return res\n        \n        last = nums[0]\n        t = 0\n        for num in nums:\n            if num == last:\n                t += 1\n            else:\n                res -= getTotal(last,t)\n                last = num\n                t = 1\n\n        res -= getTotal(last,t)\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.numGoodSubarrays(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
