    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:\n        points = set()\n        row, col, diagonal, antiDiagonal = Counter(), Counter(), Counter(), Counter()\n        for r, c in lamps:\n            if (r, c) in points:\n                continue\n            points.add((r, c))\n            row[r] += 1\n            col[c] += 1\n            diagonal[r - c] += 1\n            antiDiagonal[r + c] += 1\n\n        ans = [0] * len(queries)\n        for i, (r, c) in enumerate(queries):\n            if row[r] or col[c] or diagonal[r - c] or antiDiagonal[r + c]:\n                ans[i] = 1\n            for x in range(r - 1, r + 2):\n                for y in range(c - 1, c + 2):\n                    if x < 0 or y < 0 or x >= n or y >= n or (x, y) not in points:\n                        continue\n                    points.remove((x, y))\n                    row[x] -= 1\n                    col[y] -= 1\n                    diagonal[x - y] -= 1\n                    antiDiagonal[x + y] -= 1\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.gridIllumination(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
